    19: { d: "indeterminate", m: ["{x1} = {t} + 2, {x2} = {t}, {x3} = 4{t} + 4 satisfies the three identities for every {t}: a one-parameter family of solutions, and Diophantus states it as such."] },
    20: { f: ["{x}<sub>i</sub>{x}<sub>j</sub> + 1 = {u}<sub>ij</sub>² for every pair i ≠ j, with four numbers"], d: "indeterminate", m: ["Adding {x4} = 9{t} + 6 to the preceding family, all conditions are automatic except ({t} + 2)(9{t} + 6) + 1 = (3{t} − 4)², which gives {t} = 1/16."] },
