    22: { d: "indeterminate", m: ["With product {t}² + 2{t}, {x1} = 1, {x2} = 2{t} + 4, {x3} = {t}/2: {t}² + 5{t}/2 = 4{t}² gives {t} = 5/6."] },
    23: { d: "indeterminate", m: ["With {x1} = {t}, {x2} = 1, {x3} = {t} + 1 the product is {t}² + {t}; {t}² + {t} − 1 and {t}² − 1 differ by {t} = 2{t} · ½: ({t} − ¼)² = {t}² − 1 gives {t} = 17/8."] },
